const { property_id, check_in, check_out, guests } = $input.item.json;

// Get property pricing from context or database
const basePrice = 150; // Default, would query DB
const cleaningFee = 75;
const serviceFee = 0.12; // 12%

const checkIn = new Date(check_in);
const checkOut = new Date(check_out);
const nights = Math.ceil((checkOut - checkIn) / (1000 * 60 * 60 * 24));

if (nights <= 0) {
  return { error: 'Invalid date range' };
}

const nightsTotal = basePrice * nights;
const subtotal = nightsTotal + cleaningFee;
const serviceFeeAmount = subtotal * serviceFee;
const total = subtotal + serviceFeeAmount;

// Weekly discount
let discount = 0;
if (nights >= 7) discount = 0.10;
if (nights >= 28) discount = 0.20;

const discountAmount = nightsTotal * discount;
const finalTotal = total - discountAmount;

return {
  property_id,
  nights,
  base_price_per_night: basePrice,
  nights_total: nightsTotal,
  cleaning_fee: cleaningFee,
  service_fee: serviceFeeAmount.toFixed(2),
  discount_percent: discount * 100,
  discount_amount: discountAmount.toFixed(2),
  total: finalTotal.toFixed(2),
  currency: 'USD'
};

